-- Facture_Par_Bail
SELECT "C"."ID_BAIL" AS "N° Bail", "L"."NOM" AS "Nom Locataire", "L"."PRENOM" AS "Prénom Locataire", "F"."DATE_FACTURE" AS "Date Facture", "F"."OBJET" AS "Nature des Travaux", "F"."MONTANT" AS "Montant" FROM "FACTURE" AS "F" INNER JOIN "BIEN" AS "B" ON "F"."ID_BIEN" = "B"."ID_BIEN" INNER JOIN "CONTRAT_BAIL" AS "C" ON "B"."ID_BIEN" = "C"."ID_BIEN" INNER JOIN "LOCATAIRE" AS "L" ON "C"."ID_LOCATAIRE" = "L"."ID_LOCATAIRE" WHERE "F"."DATE_FACTURE" >= "C"."DATE_DEBUT" AND ( "F"."DATE_FACTURE" <= "C"."DATE_FIN" OR "C"."DATE_FIN" IS NULL ) ORDER BY "C"."ID_BAIL", "F"."DATE_FACTURE";

-- Recap_Facture_Bien
SELECT "B"."ADRESSE" AS "Adresse Bien", "B"."VILLE" AS "Ville", "F"."DATE_FACTURE" AS "Date", "F"."OBJET" AS "Travaux", "F"."MONTANT" AS "Coût", "E"."NOM_SOCIETE" AS "Entreprise" FROM "FACTURE" AS "F" INNER JOIN "BIEN" AS "B" ON "F"."ID_BIEN" = "B"."ID_BIEN" INNER JOIN "ENTREPRENEUR" AS "E" ON "F"."ID_ENTREPRENEUR" = "E"."ID_ENTREPRENEUR" ORDER BY "B"."ADRESSE", "F"."DATE_FACTURE";

-- Recap_Facture_Entrepreneur
SELECT "E"."NOM_SOCIETE" AS "Entrepreneur", "E"."METIER" AS "Métier", "B"."ADRESSE" AS "Adresse du Bien", "B"."VILLE" AS "Ville", "F"."DATE_FACTURE" AS "Date Facture", "F"."OBJET" AS "Motif", "F"."MONTANT" AS "Montant Facture" FROM "FACTURE" AS "F" INNER JOIN "ENTREPRENEUR" AS "E" ON "F"."ID_ENTREPRENEUR" = "E"."ID_ENTREPRENEUR" INNER JOIN "BIEN" AS "B" ON "F"."ID_BIEN" = "B"."ID_BIEN" ORDER BY "F"."DATE_FACTURE";

-- Recap_Loyer_Bien
SELECT "B"."ADRESSE" AS "Adresse du Bien", "L"."NOM" AS "Nom Locataire", "L"."PRENOM" AS "Prénom Locataire", "P"."DATE" AS "Date Paiement", "P"."MONTANT" AS "Montant Payé", "P"."MOYEN_PAIEMENT" AS "Moyen Paiement" FROM "PAIEMENT" AS "P" INNER JOIN "CONTRAT_BAIL" AS "C" ON "P"."ID_BAIL" = "C"."ID_BAIL" INNER JOIN "BIEN" AS "B" ON "C"."ID_BIEN" = "B"."ID_BIEN" INNER JOIN "LOCATAIRE" AS "L" ON "C"."ID_LOCATAIRE" = "L"."ID_LOCATAIRE" ORDER BY "B"."ADRESSE", "P"."DATE" DESC;

-- Requete 1
SELECT * FROM "BIEN" WHERE "VILLE" = 'Poitiers' AND "SURFACE" > 80 AND "LOYER_HC" < 800 AND "ID_BIEN" IN ( SELECT "ID_BIEN" FROM "CONTRAT_BAIL" WHERE "DATE_FIN" <= CURRENT_DATE );

-- Requête 10
SELECT DISTINCT "E"."NOM_SOCIETE" FROM "ENTREPRENEUR" AS "E" INNER JOIN "FACTURE" AS "F" ON "E"."ID_ENTREPRENEUR" = "F"."ID_ENTREPRENEUR" INNER JOIN "BIEN" AS "B" ON "F"."ID_BIEN" = "B"."ID_BIEN" WHERE "B"."VILLE" = 'Poitiers' AND "E"."ID_ENTREPRENEUR" NOT IN ( SELECT "F"."ID_ENTREPRENEUR" FROM "FACTURE" AS "F" INNER JOIN "BIEN" AS "B" ON "F"."ID_BIEN" = "B"."ID_BIEN" WHERE "B"."VILLE" = 'Chatellerault' );

-- Requête 2
SELECT "A"."NOM", "A"."VILLE" FROM "AGENCE" AS "A" INNER JOIN "CONTRAT_BAIL" AS "C" ON "A"."ID_AGENCE" = "C"."ID_AGENCE" INNER JOIN "LOCATAIRE" AS "L" ON "C"."ID_LOCATAIRE" = "L"."ID_LOCATAIRE" WHERE "L"."NOM" = 'LACROIX' AND "L"."PRENOM" = 'Anne-Claire' LIMIT 1;

-- Requête 3
SELECT "B"."ADRESSE", "B"."VILLE", "B"."SURFACE" FROM "BIEN" AS "B" INNER JOIN "CONTRAT_BAIL" AS "C" ON "B"."ID_BIEN" = "C"."ID_BIEN" WHERE "B"."SURFACE" > 80 AND "C"."DATE_DEBUT" <= '2024-12-10' AND ( "C"."DATE_FIN" IS NULL OR "C"."DATE_FIN" >= '2024-12-10' );

-- Requête 4
SELECT "B"."ID_BIEN", "B"."ADRESSE", "B"."VILLE" FROM "BIEN" AS "B" INNER JOIN "AGENCE" AS "A" ON "B"."ID_AGENCE" = "A"."ID_AGENCE" WHERE "B"."TYPE_MANDAT" = 'GESTION' AND "A"."ID_AGENCE" = ( SELECT "ID_AGENCE" FROM "PERSONNEL" WHERE "NOM" = 'CHARRAUD' AND "PRENOM" = 'Jérôme' );

-- Requête 5
SELECT "L"."NOM", "L"."PRENOM" FROM "LOCATAIRE" "L" INNER JOIN "CONTRAT_BAIL" "C" ON "L"."ID_LOCATAIRE" = "C"."ID_LOCATAIRE" INNER JOIN "BIEN" "B" ON "C"."ID_BIEN" = "B"."ID_BIEN" WHERE "B"."ID_PROPRIO" = ( SELECT "B"."ID_PROPRIO" FROM "BIEN" AS "B" INNER JOIN "CONTRAT_BAIL" AS "C" ON "B"."ID_BIEN" = "C"."ID_BIEN" INNER JOIN "LOCATAIRE" AS "L" ON "C"."ID_LOCATAIRE" = "L"."ID_LOCATAIRE" WHERE "L"."NOM" = 'LAFFERIERE' AND "L"."PRENOM" = 'Françis' );

-- Requête 6
SELECT "F"."ID_FACTURE", "F"."MONTANT", "F"."DATE_FACTURE" FROM "FACTURE" AS "F" INNER JOIN "BIEN" AS "B" ON "F"."ID_BIEN" = "B"."ID_BIEN" INNER JOIN "CONTRAT_BAIL" AS "C" ON "B"."ID_BIEN" = "C"."ID_BIEN" WHERE "F"."OBJET" LIKE '%Remplacement Chaudière%' AND YEAR( "C"."DATE_DEBUT" ) = 2018;

-- Requête 7
SELECT "B"."ADRESSE", SUM( "P"."MONTANT" ) AS "TOTAL_LOYERS" FROM "PAIEMENT" AS "P" JOIN "CONTRAT_BAIL" AS "C" ON "P"."ID_BAIL" = "C"."ID_BAIL" JOIN "BIEN" AS "B" ON "C"."ID_BIEN" = "B"."ID_BIEN" WHERE "B"."TYPE_MANDAT" = 'GESTION' AND "P"."DATE" >= '2025-01-01' GROUP BY "B"."ADRESSE";

-- Requête 8
SELECT "P"."NOM", "P"."PRENOM", COUNT( "B"."ID_BIEN" ) AS "NB_BIENS_LOUES" FROM "PROPRIETAIRE" "P" JOIN "BIEN" "B" ON "P"."ID_PROPRIO" = "B"."ID_PROPRIO" INNER JOIN "CONTRAT_BAIL" AS "C" ON "B"."ID_BIEN" = "C"."ID_BIEN" WHERE "C"."DATE_FIN" IS NULL OR "C"."DATE_FIN" > CURRENT_DATE GROUP BY "P"."NOM", "P"."PRENOM" ORDER BY "NB_BIENS_LOUES" DESC LIMIT 1;

-- Requête 9
SELECT SUM( "F"."MONTANT" ) FROM "FACTURE" AS "F" INNER JOIN "CONTRAT_BAIL" AS "C" ON "F"."ID_BIEN" = "C"."ID_BIEN" WHERE "C"."ID_BAIL" = 99 AND "F"."DATE_FACTURE" BETWEEN "C"."DATE_DEBUT" AND IFNULL( "C"."DATE_FIN", CURRENT_DATE );

